"""
secrets_service - Verschluesselt und entschluesselt Secrets.

Die Secrets liegen verschluesselt in Umgebungsvariablen. Der Fernet-Key wird aus
dem Windows Credential Manager gelesen.
"""

import importlib
import os
from typing import Any

WIN32CRED: Any | None
try:
    WIN32CRED = importlib.import_module("win32cred")
except ImportError:
    WIN32CRED = None

FERNET_MODULE: Any | None
try:
    FERNET_MODULE = importlib.import_module("cryptography.fernet")
except ImportError:
    FERNET_MODULE = None

# True wenn die Umgebungsvariable ENVIRONMENT auf "dev" gesetzt ist.
is_dev: bool = os.getenv("ENVIRONMENT", "").lower() == "dev"

# Standardwerte, die als "leer" betrachtet werden, z. B. bei Datenbereinigung.
empty_values: list[str] = ["", "(not set)", "(null)", "NA", "N/A"]


def _read_fernet_key() -> str:
    """Liest den Fernet-Key aus dem Windows Credential Manager."""
    if WIN32CRED is None:
        raise RuntimeError("win32cred ist nicht verfuegbar")

    cred = WIN32CRED.CredRead("App/Prod/FernetKey", WIN32CRED.CRED_TYPE_GENERIC)
    blob = cred.get("CredentialBlob")
    if isinstance(blob, bytes):
        return blob.decode("utf-16le")
    if isinstance(blob, str):
        return blob
    raise RuntimeError("CredentialBlob fuer App/Prod/FernetKey ist ungueltig")


def _create_fernet() -> Any:
    """Erstellt eine Fernet-Instanz mit dem Credential-Manager-Key."""
    if FERNET_MODULE is None:
        raise RuntimeError("cryptography ist nicht verfuegbar")

    key = _read_fernet_key()
    return FERNET_MODULE.Fernet(key.encode())


def decode_secret(secret_name: str) -> str:
    """Entschluesselt einen verschluesselten Wert aus einer Umgebungsvariable.

    Args:
        secret_name: Name der Umgebungsvariable, die den verschluesselten Wert enthaelt.

    Returns:
        Der entschluesselte Wert als String.

    Raises:
        KeyError: Wenn die Umgebungsvariable nicht gesetzt ist.
        RuntimeError: Wenn benoetigte Abhaengigkeiten oder Credentials fehlen.
    """
    secret_enc = os.environ[secret_name].encode()
    fernet = _create_fernet()
    secret = fernet.decrypt(secret_enc)
    return str(secret.decode())


def encrypt(str_to_encrypt: str) -> str:
    """Verschluesselt einen Klartext-String mit dem Fernet-Key.

    Args:
        str_to_encrypt: Der zu verschluesselnde Klartext-String.

    Returns:
        Der verschluesselte Wert als Fernet-Token.

    Raises:
        RuntimeError: Wenn benoetigte Abhaengigkeiten oder Credentials fehlen.
    """
    fernet = _create_fernet()
    encrypted = fernet.encrypt(str_to_encrypt.encode())
    return str(encrypted.decode())
